interface.definition:
a!localVariables(
  local!processTypes: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3811116"(),
  local!actionType,
  local!processType,
  local!showOnlyErrors,
  {
    #"SYSTEM_SYSRULES_cardLayout"(
      style: "STANDARD",
      showBorder: false,
      contents: {
        #"SYSTEM_SYSRULES_sideBySideLayout"(
          alignVertical: "MIDDLE",
          items: {
            #"SYSTEM_SYSRULES_sideBySideItem"(
              item: #"SYSTEM_SYSRULES_dropdownField_v1"(
                label: "Process Name",
                placeholder: "-- Select -- ",
                value: local!processType,
                choicelabels: index(local!processTypes, "processName", {}),
                choiceValues: index(local!processTypes, "processName", {}),
                saveInto: local!processType
              )
            ),
            #"SYSTEM_SYSRULES_sideBySideItem"(
              item: #"SYSTEM_SYSRULES_dropdownField_v1"(
                label: "Action Type",
                placeholder: "-- Select --",
                value: local!actionType,
                saveInto: local!actionType,
                choiceLabels: {
                  #"_a-0000e6cf-8b0b-8000-9c00-011c48011c48_3753256",
                  #"_a-0000e6cf-8b0b-8000-9c00-011c48011c48_3783173",
                  #"_a-0000e6cf-8b0b-8000-9c00-011c48011c48_3753352",
                  #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3832511",
                  #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3815380"
                },
                choiceValues: {
                  #"_a-0000e6cf-8b0b-8000-9c00-011c48011c48_3753256",
                  #"_a-0000e6cf-8b0b-8000-9c00-011c48011c48_3783173",
                  #"_a-0000e6cf-8b0b-8000-9c00-011c48011c48_3753352",
                  #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3832511",
                  #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3815380"
                }
              )
            ),
            #"SYSTEM_SYSRULES_sideBySideItem"(
              item: #"SYSTEM_SYSRULES_checkboxField"(
                /*align: "CENTER",*/
                /*labelPosition: "COLLAPSED",*/
                value: local!showOnlyErrors,
                choiceLabels: { "Only Show Errors" },
                choiceValues: false,
                saveInto: local!showOnlyErrors
              )
            )
          }
        ),
        #"SYSTEM_SYSRULES_richTextDisplayField"(
          align: "RIGHT",
          value: {
            #"SYSTEM_SYSRULES_richTextIcon"(
              icon: "refresh",
              linkStyle: "STANDALONE",
              /*size: "MEDIUM",*/
              link: #"SYSTEM_SYSRULES_dynamicLink"(
                saveInto: a!save(
                  { local!processType, local!actionType },
                  null
                )
              )
            ),
            #"SYSTEM_SYSRULES_richTextItem_v1"(
              text: " Clear Filters",
              /*size: "MEDIUM",*/
              style: "STRONG",
              linkStyle: "STANDALONE",
              link: #"SYSTEM_SYSRULES_dynamicLink"(
                saveInto: a!save(
                  { local!processType, local!actionType },
                  null
                )
              )
            )
          }
        )
      }
    ),
    #"SYSTEM_SYSRULES_gridField_v1"(
      /*borderStyle: "LIGHT",*/
      shadeAlternateRows: false,
      data: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3811110"(
        pagingInfo: fv!pagingInfo,
        processName: local!processType,
        actionType: local!actionType,
        successFilter: local!showOnlyErrors
      ),
      initialSorts: #"SYSTEM_SYSRULES_sortInfo"(field: "actionDatetime"),
      pageSize: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3851952",
      columns: {
        #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3840347"(id: 1),
        #"SYSTEM_SYSRULES_gridColumn"(
          align: "CENTER",
          label: "Success?",
          value: #"SYSTEM_SYSRULES_richTextDisplayField"(
            align: "CENTER",
            value: #"SYSTEM_SYSRULES_richTextIcon"(
              icon: if(
                fv!row.isSuccess,
                "check-circle",
                "exclamation-circle"
              ),
              size: "MEDIUM",
              color: if(fv!row.isSuccess, "POSITIVE", "NEGATIVE")
            )
          )
        )
      }
    )
  }
)
